import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { buildPath, exampleFromSchema, formatBody, groupByTag, listEndpoints, requestTemplate } from '../src/lib/codelab/openapi.js'

// Real documents generated by FastAPI from the tasks and auth starters (regenerate them if
// the starters' routes change).
const { auth, tasks } = JSON.parse(readFileSync(new URL('./fixtures/starter-openapi.json', import.meta.url), 'utf8'))

const find = (doc, id) => listEndpoints(doc).find((endpoint) => endpoint.id === id)

test('endpoints are listed by tag with their auth requirement', () => {
  const endpoints = listEndpoints(auth)
  assert.ok(endpoints.some((endpoint) => endpoint.id === 'POST /api/auth/login'))
  assert.equal(find(auth, 'GET /api/auth/me').secured, true)
  assert.equal(find(auth, 'POST /api/auth/register').secured, false)
  assert.deepEqual(groupByTag(endpoints).map((group) => group.tag), ['auth', 'tasks', 'health'])
})

test('request templates are prefilled from the Pydantic models', () => {
  const register = requestTemplate(find(auth, 'POST /api/auth/register'), auth)
  assert.equal(register.contentType, 'application/json')
  const body = JSON.parse(register.body)
  assert.deepEqual(Object.keys(body).sort(), ['email', 'full_name', 'password'])
  assert.equal(body.email, 'learner@example.com', 'the email pattern gets a real-looking address')
  assert.equal(body.password, 'password123', 'register and login use the same password')

  const login = requestTemplate(find(auth, 'POST /api/auth/login'), auth)
  assert.equal(login.contentType, 'application/x-www-form-urlencoded')
  const fields = new URLSearchParams(login.body)
  assert.equal(fields.get('username'), 'learner@example.com')
  assert.equal(fields.get('password'), 'password123')
  assert.equal(fields.get('client_id'), null, 'optional OAuth2 fields are left out')
  assert.ok(!fields.has('grant_type') || fields.get('grant_type') === 'password')

  const create = JSON.parse(requestTemplate(find(tasks, 'POST /api/tasks'), tasks).body)
  assert.equal(create.priority, 'medium', 'defaults are used')
  assert.ok(['low', 'medium', 'high'].includes(create.priority))
})

test('path and query parameters build the final path', () => {
  const patch = requestTemplate(find(tasks, 'PATCH /api/tasks/{task_id}'), tasks)
  assert.deepEqual(patch.pathParams, [{ name: 'task_id', value: '1' }])
  assert.equal(buildPath(patch.pathTemplate, patch.pathParams, patch.query), '/api/tasks/1')
  const list = requestTemplate(find(tasks, 'GET /api/tasks'), tasks)
  assert.deepEqual(list.query.map((param) => param.name), ['done', 'priority', 'page', 'size'])
  assert.ok(list.query.every((param) => !param.enabled), 'optional query parameters start switched off')
  assert.equal(buildPath('/api/tasks', [], [{ name: 'done', value: 'false', enabled: true }, { name: 'page', value: '2', enabled: false }]), '/api/tasks?done=false')
  assert.equal(buildPath('/api/items/{name}', [{ name: 'name', value: 'a b/c' }]), '/api/items/a%20b%2Fc')
})

test('example values follow the schema', () => {
  assert.equal(exampleFromSchema({ anyOf: [{ type: 'null' }, { type: 'integer', minimum: 5 }] }), 5)
  assert.deepEqual(exampleFromSchema({ type: 'array', items: { type: 'boolean' } }), [false])
  assert.equal(exampleFromSchema({ type: 'string', format: 'date' }), '2026-01-01')
  assert.equal(formatBody('{"a":1}', [['content-type', 'application/json']]), '{\n  "a": 1\n}')
  assert.equal(formatBody('plain', [['content-type', 'text/plain']]), 'plain')
})
